import { AnimationEvent } from '@angular/animations';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
  inject,
  numberAttribute,
} from '@angular/core';
import { tooltipAnimation } from './tooltip.animation';

interface TooltipAnimationPosition {
  x: number;
  y: number;
}

@Component({
  selector: 'q-tooltip',
  templateUrl: './tooltip.component.html',
  styleUrls: ['./tooltip.component.scss'],
  animations: [tooltipAnimation],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTooltipComponent {
  @Output() readonly closeAnimationDone = new EventEmitter<void>();

  @Input() value = '';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-tooltip';

  // TODO: Remove the following inputs once this component is made private
  @Input({ transform: numberAttribute }) showDelay = 150;
  @Input({ transform: numberAttribute }) hideDelay = 150;

  get isOpen(): boolean {
    return this._isOpen;
  }
  set isOpen(value: boolean) {
    this._isOpen = value;
    this._changeDetectorRef.detectChanges();
  }

  get position(): string | null {
    return this._position;
  }

  set position(value: string | null) {
    this._position = value;
    this._changeDetectorRef.detectChanges();
  }

  @HostBinding('class') hostClass = 'q-tooltip';

  _isOpen = false;
  _position: string | null = null;
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);

  _markForCheck(): void {
    this._changeDetectorRef.markForCheck();
  }

  _onAnimationDone(event: AnimationEvent): void {
    if (event.fromState === 'open' && event.toState === 'closed') {
      this.closeAnimationDone.emit();
    }
  }

  get translationValues(): TooltipAnimationPosition {
    if (this.position === 'right') {
      return {
        x: -4,
        y: 0,
      };
    } else if (this.position === 'left') {
      return {
        x: 4,
        y: 0,
      };
    } else if (this.position === 'top') {
      return {
        x: 0,
        y: 4,
      };
    } else if (this.position === 'bottom') {
      return {
        x: 0,
        y: -4,
      };
    }

    return {
      x: 0,
      y: 0,
    };
  }
}
