import { FocusMonitor } from '@angular/cdk/a11y';
import {
  ConnectedPosition,
  Overlay,
  OverlayContainer,
  OverlayRef,
  ScrollDispatcher,
} from '@angular/cdk/overlay';
import { ComponentPortal } from '@angular/cdk/portal';

import {
  AfterViewInit,
  Directive,
  ElementRef,
  HostListener,
  Input,
  NgZone,
  OnDestroy,
  inject,
  numberAttribute,
  DOCUMENT,
} from '@angular/core';
import {
  QDestroyService,
  QPlatformService,
} from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs';
import { QTooltipComponent } from './tooltip.component';
import { QTooltipPosition } from './types/tooltip-position.type';

const position = {
  top: {
    originX: 'center',
    originY: 'top',
    overlayX: 'center',
    overlayY: 'bottom',
    offsetY: -10,
    panelClass: 'top',
  } as ConnectedPosition,
  right: {
    originX: 'end',
    originY: 'center',
    overlayX: 'start',
    overlayY: 'center',
    offsetX: 10,
    panelClass: 'right',
  } as ConnectedPosition,
  bottom: {
    originX: 'center',
    originY: 'bottom',
    overlayX: 'center',
    overlayY: 'top',
    offsetY: 10,
    panelClass: 'bottom',
  } as ConnectedPosition,
  left: {
    originX: 'start',
    originY: 'center',
    overlayX: 'end',
    overlayY: 'center',
    offsetX: -10,
    panelClass: 'left',
  } as ConnectedPosition,
};

@Directive({
  selector: '[qTooltip]',
  providers: [QDestroyService],
})
export class QTooltipDirective implements OnDestroy, AfterViewInit {
  @Input('qTooltipPosition') placement: QTooltipPosition = 'right';
  @Input({ alias: 'qTooltipShowDelay', transform: numberAttribute }) showDelay = 0;
  @Input({ alias: 'qTooltipHideDelay', transform: numberAttribute }) hideDelay = 0;
  @Input({ alias: 'qTooltipLongPressDelay', transform: numberAttribute }) longPressDelay = 500;
  @Input('qTooltip') tooltipValue = '';
  @Input('qTooltipDataQt') dataQt = 'q-tooltip';
  @Input({
    alias: 'qTooltipTouchendHideDelay',
    transform: numberAttribute,
  })
  touchendHideDelay = 1500;

  @HostListener('mouseenter') _onMouseEnter(): void {
    if (this._isMobilePlatform) return;

    this._show(this.showDelay);
  }

  @HostListener('mouseleave', ['$event']) _onMouseLeave(event: MouseEvent): void {
    if (this._isMobilePlatform) return;

    const newTarget = (event as MouseEvent).relatedTarget as Node | null;
    if (!newTarget || !this._elementRef.nativeElement.contains(newTarget)) {
      this._hide(this.hideDelay);
    }
  }

  @HostListener('wheel', ['$event']) _onWheelMove(event: WheelEvent): void {
    if (this._tooltipComponent?.isOpen) {
      const elementUnderPointer = this._document.elementFromPoint(event.clientX, event.clientY);
      const element = this._elementRef.nativeElement;

      // `mouseleave` event won't fire if the user scrolls away using the wheel without moving
      // their cursor. So we find the element under the user's cursor and close the tooltip if
      // it's not the trigger.
      if (elementUnderPointer !== element && !element.contains(elementUnderPointer)) {
        this._hide(0);
      }
    }
  }

  @HostListener('touchstart') _onTouchStart(): void {
    this._show(this.longPressDelay);
  }

  @HostListener('touchend') _onTouchEnd(): void {
    this._hide(this.touchendHideDelay);
  }

  _overlayRef: OverlayRef | null = null;

  private _tooltipComponent: QTooltipComponent | null = null;
  private _hideTimeout: ReturnType<typeof setTimeout> | null = null;
  private _showTimeout: ReturnType<typeof setTimeout> | null = null;
  private readonly _overlay = inject(Overlay);
  private readonly _elementRef = inject(ElementRef);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _platform = inject(QPlatformService);
  private readonly _ngZone = inject(NgZone);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _document = inject(DOCUMENT);
  private readonly _isMobilePlatform = this._platform.ANDROID || this._platform.IOS;
  private readonly _scrollDispatcher = inject(ScrollDispatcher);
  private readonly _overlayContainer = inject(OverlayContainer);

  ngOnDestroy(): void {
    this._disposeTooltip();
  }

  ngAfterViewInit(): void {
    this._focusMonitor
      .monitor(this._elementRef)
      .pipe(takeUntil(this._destroy$))
      .subscribe((origin) => {
        if (!origin) {
          this._ngZone.run(() => this._hide(this.hideDelay));
        } else if (origin === 'keyboard') {
          this._ngZone.run(() => this._show(this.showDelay));
        }
      });
  }

  _getPositions(): ConnectedPosition[] {
    if (this.placement === 'right') {
      return [position.right, position.left, position.top, position.bottom];
    } else if (this.placement === 'left') {
      return [position.left, position.right, position.top, position.bottom];
    } else if (this.placement === 'bottom') {
      return [position.bottom, position.top, position.right, position.left];
    } else return [position.top, position.bottom, position.right, position.left];
  }

  _getTooltipElement(): QTooltipComponent | null {
    return this._tooltipComponent;
  }

  private _show(delay: number): void {
    if (!this.tooltipValue) return;

    this._clearHideTimer();
    this._showTimeout = setTimeout(() => {
      this._createAndAttachTooltip();
      this._initializeTooltipProperties();

      if (this._tooltipComponent) this._tooltipComponent.isOpen = true;
    }, delay);
  }

  private _hide(delay: number): void {
    this._clearShowTimer();
    this._hideTimeout = setTimeout(() => {
      if (this._tooltipComponent) this._tooltipComponent.isOpen = false;
    }, delay);
  }

  private _createAndAttachTooltip(): void {
    if (this._overlayRef) return;
    this._relocateOverlayContainer();

    const scrollableAncestors = this._scrollDispatcher.getAncestorScrollContainers(
      this._elementRef,
    );

    const positionStrategy = this._overlay
      .position()
      .flexibleConnectedTo(this._elementRef)
      .withPositions(this._getPositions())
      .withScrollableContainers(scrollableAncestors)
      .withFlexibleDimensions(false);

    this._overlayRef = this._overlay.create({
      positionStrategy,
      scrollStrategy: this._overlay.scrollStrategies.reposition({ scrollThrottle: 20 }),
    });

    positionStrategy.positionChanges.pipe(takeUntil(this._destroy$)).subscribe((pos) => {
      if (!this._tooltipComponent) return;

      if (
        pos.scrollableViewProperties.isOverlayClipped &&
        this._tooltipComponent.isOpen &&
        this._tooltipComponent.position
      ) {
        this._tooltipComponent.isOpen = false;
      }

      this._tooltipComponent.position = pos.connectionPair.panelClass as string;
    });

    this._tooltipComponent = this._overlayRef.attach(
      new ComponentPortal(QTooltipComponent),
    ).instance;
  }

  private _disposeTooltip(): void {
    this._overlayRef?.dispose();
    this._overlayRef = null;
  }

  private _initializeTooltipProperties(): void {
    if (!this._tooltipComponent) return;

    this._tooltipComponent.value = this.tooltipValue;
    this._tooltipComponent.dataQt = this.dataQt;

    this._tooltipComponent.closeAnimationDone
      ?.pipe(takeUntil(this._destroy$))
      .subscribe(() => this._disposeTooltip());
  }

  private _relocateOverlayContainer(): void {
    const originElement = this._elementRef.nativeElement;
    const popoverContainer = originElement.closest('[popover][q-popover], [popover][qPopover]');
    const dialogContainer = originElement.closest('dialog[q-dialog], dialog[qDialog]');
    const overlayContainer = this._overlayContainer.getContainerElement();

    if (popoverContainer?.contains(originElement)) {
      overlayContainer.parentNode?.removeChild(overlayContainer);
      popoverContainer.appendChild(overlayContainer);
    } else if (dialogContainer?.contains(originElement)) {
      overlayContainer.parentNode?.removeChild(overlayContainer);
      dialogContainer.appendChild(overlayContainer);
    } else if (overlayContainer.parentNode !== this._document.body) {
      this._document.body.appendChild(this._overlayContainer.getContainerElement());
    }
  }

  private _clearShowTimer(): void {
    if (this._showTimeout) {
      clearTimeout(this._showTimeout);
      this._showTimeout = null;
    }
  }

  private _clearHideTimer(): void {
    if (this._hideTimeout) {
      clearTimeout(this._hideTimeout);
      this._hideTimeout = null;
    }
  }
}
